/**
 * Problem: 1594. Maximum Non Negative Product in a Matrix
 * Difficulty: Medium
 * Language: Java
 * 
 * Approach:
 * At any cell (i, j), multiplying by a negative number can flip a minimum product
 * to a maximum product and vice-versa. Therefore, we use Dynamic Programming to track
 * both the maximum and minimum products to reach cell (i, j) from (0, 0).
 * 
 * For each cell (i, j), we consider transitions from (i - 1, j) and (i, j - 1),
 * computing all 4 possible products with grid[i][j], and taking the maximum and minimum.
 * Products can reach up to 4^29, which comfortably fits in a 64-bit signed long.
 * Finally, if the maximum product at (m - 1, n - 1) is negative, we return -1;
 * otherwise, we return maxProd[m - 1][n - 1] % (10^9 + 7).
 * 
 * Time Complexity: O(m * n)
 * Space Complexity: O(m * n) auxiliary space
 */
class Solution {
    public int maxProductPath(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] maxProd = new long[m][n];
        long[][] minProd = new long[m][n];

        maxProd[0][0] = grid[0][0];
        minProd[0][0] = grid[0][0];

        for (int j = 1; j < n; j++) {
            maxProd[0][j] = maxProd[0][j - 1] * grid[0][j];
            minProd[0][j] = minProd[0][j - 1] * grid[0][j];
        }

        for (int i = 1; i < m; i++) {
            maxProd[i][0] = maxProd[i - 1][0] * grid[i][0];
            minProd[i][0] = minProd[i - 1][0] * grid[i][0];
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                long val = grid[i][j];
                long c1 = maxProd[i - 1][j] * val;
                long c2 = minProd[i - 1][j] * val;
                long c3 = maxProd[i][j - 1] * val;
                long c4 = minProd[i][j - 1] * val;

                maxProd[i][j] = Math.max(Math.max(c1, c2), Math.max(c3, c4));
                minProd[i][j] = Math.min(Math.min(c1, c2), Math.min(c3, c4));
            }
        }

        long ans = maxProd[m - 1][n - 1];
        if (ans < 0) {
            return -1;
        }

        long MOD = 1_000_000_007L;
        return (int) (ans % MOD);
    }
}

codes.C++:
/**
 * Problem: 1594. Maximum Non Negative Product in a Matrix
 * Difficulty: Medium
 * Language: C++
 * 
 * Approach:
 * Track both maximum and minimum path products to each cell (i, j) using Dynamic Programming.
 * Because grid elements can be negative, multiplying by a negative number can turn the smallest
 * negative product into the largest positive product.
 * Using 64-bit signed integers (long long) prevents overflow since max product <= 4^29 < 2^63 - 1.
 * 
 * Time Complexity: O(m * n)
 * Space Complexity: O(m * n) auxiliary space
 */

#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxProductPath(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        vector<vector<long long>> maxProd(m, vector<long long>(n, 0));
        vector<vector<long long>> minProd(m, vector<long long>(n, 0));

        maxProd[0][0] = minProd[0][0] = grid[0][0];

        for (int j = 1; j < n; ++j) {
            maxProd[0][j] = minProd[0][j] = maxProd[0][j - 1] * grid[0][j];
        }

        for (int i = 1; i < m; ++i) {
            maxProd[i][0] = minProd[i][0] = maxProd[i - 1][0] * grid[i][0];
        }

        for (int i = 1; i < m; ++i) {
            for (int j = 1; j < n; ++j) {
                long long val = grid[i][j];
                long long c1 = maxProd[i - 1][j] * val;
                long long c2 = minProd[i - 1][j] * val;
                long long c3 = maxProd[i][j - 1] * val;
                long long c4 = minProd[i][j - 1] * val;

                maxProd[i][j] = max({c1, c2, c3, c4});
                minProd[i][j] = min({c1, c2, c3, c4});
            }
        }

        long long ans = maxProd[m - 1][n - 1];
        if (ans < 0) {
            return -1;
        }

        long long MOD = 1000000007LL;
        return ans % MOD;
    }
};

